import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';

// Deterministic PRNG (mulberry32)
function makeRng(seed) {
  let a = seed >>> 0;
  return function rng() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Build the merged low-poly tree geometry: a cone canopy on top of a
 * cylinder trunk, merged into a single BufferGeometry with one position
 * attribute.
 */
function buildTreeGeometry() {
  const canopy = new ConeGeometry(1.0, 2.5, 6);
  const trunk = new CylinderGeometry(0.15, 0.2, 1.0, 6);

  // Trunk base sits at y=0; canopy stacked above.
  trunk.translate(0, 0.5, 0);
  canopy.translate(0, 1.0 + 1.25, 0);

  const merged = mergeGeometries([trunk, canopy], false);
  if (!merged) {
    throw new Error('Failed to merge tree geometries');
  }
  return merged;
}

/**
 * Plant an instanced forest.
 *
 * @param {object} options
 * @param {number} options.seed       Seed for deterministic placement.
 * @param {number} options.count      Number of instances.
 * @param {number} options.areaSize   Side length of the square planting area (centered on origin).
 * @param {number} [options.minScale] Minimum per-instance uniform scale.
 * @param {number} [options.maxScale] Maximum per-instance uniform scale.
 * @returns {InstancedMesh}
 */
export function plantForest({
  seed,
  count,
  areaSize,
  minScale = 0.8,
  maxScale = 1.4,
}) {
  const geometry = buildTreeGeometry();
  const material = new MeshLambertMaterial({ color: 0x3f7a3f });
  const mesh = new InstancedMesh(geometry, material, count);

  const rng = makeRng(seed);
  const half = areaSize / 2;
  const matrix = new Matrix4();
  const position = new Vector3();
  const quaternion = new Quaternion();
  const scale = new Vector3();
  const yAxis = new Vector3(0, 1, 0);

  for (let i = 0; i < count; i++) {
    position.set(
      (rng() * 2 - 1) * half,
      0,
      (rng() * 2 - 1) * half,
    );
    quaternion.setFromAxisAngle(yAxis, rng() * Math.PI * 2);
    const s = minScale + rng() * (maxScale - minScale);
    scale.set(s, s, s);

    mesh.setMatrixAt(i, matrix.compose(position, quaternion, scale));
  }

  mesh.instanceMatrix.needsUpdate = true;

  return mesh;
}

/**
 * Decompose instance i's matrix into {position, scale}.
 *
 * @param {InstancedMesh} mesh
 * @param {number} i Instance index
 */
export function treeTransform(mesh, i) {
  const matrix = new Matrix4();
  mesh.getMatrixAt(i, matrix);

  const position = new Vector3();
  const rotation = new Quaternion();
  const scale = new Vector3();
  matrix.decompose(position, rotation, scale);

  return { position, rotation, scale };
}

