import { describe, it, expect } from 'vitest';
import { plantForest, treeTransform } from '../src/forest.js';

const OPTIONS = {
  seed: 1234,
  count: 64,
  areaSize: 40,
  minScale: 0.7,
  maxScale: 1.8,
};

describe('plantForest', () => {
  it('creates an InstancedMesh with exactly count instances regardless of camera or frustum', () => {
    const mesh = plantForest(OPTIONS);
    expect(mesh.count).toBe(OPTIONS.count);
    expect(mesh.instanceMatrix.count).toBe(OPTIONS.count);

    // Instance count must not depend on any camera or frustum culling state.
    mesh.frustumCulled = false;
    expect(mesh.count).toBe(OPTIONS.count);
    mesh.frustumCulled = true;
    // No camera is ever involved; count stays the same.
    expect(mesh.count).toBe(OPTIONS.count);
  });

  it('places every tree inside the square area bounds', () => {
    const { areaSize } = OPTIONS;
    const half = areaSize / 2;
    const mesh = plantForest(OPTIONS);

    for (let i = 0; i < mesh.count; i++) {
      const { position } = treeTransform(mesh, i);
      expect(position.x).toBeGreaterThanOrEqual(-half);
      expect(position.x).toBeLessThanOrEqual(half);
      expect(position.z).toBeGreaterThanOrEqual(-half);
      expect(position.z).toBeLessThanOrEqual(half);
    }
  });

  it('keeps all per-instance scales within [minScale, maxScale]', () => {
    const { minScale, maxScale } = OPTIONS;
    const mesh = plantForest(OPTIONS);

    for (let i = 0; i < mesh.count; i++) {
      const { scale } = treeTransform(mesh, i);
      // Uniform scale: x == y == z
      expect(scale.x).toBeCloseTo(scale.y, 6);
      expect(scale.y).toBeCloseTo(scale.z, 6);
      expect(scale.x).toBeGreaterThanOrEqual(minScale);
      expect(scale.x).toBeLessThanOrEqual(maxScale);
    }
  });

  it('is deterministic for identical seeds and differs across seeds', () => {
    const a = plantForest({ ...OPTIONS, seed: 42 });
    const a2 = plantForest({ ...OPTIONS, seed: 42 });
    const b = plantForest({ ...OPTIONS, seed: 1337 });

    const matA = [];
    const matA2 = [];
    const matB = [];
    for (let i = 0; i < OPTIONS.count; i++) {
      matA.push(Array.from(a.instanceMatrix.array.slice(i * 16, i * 16 + 16)));
      matA2.push(
        Array.from(a2.instanceMatrix.array.slice(i * 16, i * 16 + 16)),
      );
      matB.push(Array.from(b.instanceMatrix.array.slice(i * 16, i * 16 + 16)));
    }

    expect(matA2).toEqual(matA);
    expect(matB).not.toEqual(matA);
  });

  it('merges canopy and trunk into one geometry with a single position attribute', () => {
    const mesh = plantForest(OPTIONS);
    const geometry = mesh.geometry;
    expect(geometry.attributes.position).toBeDefined();
    // Exactly one position attribute (merged, not grouped).
    expect(Object.keys(geometry.attributes).filter((k) => k === 'position'))
      .toHaveLength(1);
    expect(geometry.groups).toHaveLength(0);
    // Merged vertex count = cone + cylinder contributions.
    expect(geometry.attributes.position.count).toBeGreaterThan(0);
  });
});

